def seed_configuration(apps, schema_editor):
    """Initial reporting units derived from the Consolidation Matrix (every technology / circle of the dashboard site
    master), active from the earliest On-Air date of their sites (or their first daily record when no site has an
    On-Air date), and the initial coverage threshold: 100 %, the existing CSV Arrival Tracker rule (every On-Air site
    has a record). Both are recorded in their audit history; Admins change them afterwards."""
    from datetime import date

    from django.db.models import Min
    Site = apps.get_model('sitedata', 'Site')
    Daily = apps.get_model('sitedata', 'DailySitePerformance')
    Unit = apps.get_model('sitedata', 'ReportingUnit')
    Change = apps.get_model('sitedata', 'ReportingUnitChange')
    Threshold = apps.get_model('sitedata', 'CoverageThreshold')
    reason = 'Initial configuration derived from the Consolidation Matrix (migration sitedata 0003).'
    units = (Site.objects.filter(reporting_scope='dashboard').exclude(technology='').values('technology', 'circle')
             .annotate(first_on_air=Min('on_air_date')).order_by('technology', 'circle'))
    for row in units:
        first = row['first_on_air'] or Daily.objects.filter(technology=row['technology'], circle=row['circle']).aggregate(d=Min('report_date'))['d']
        first = first or date.today()
        unit = Unit.objects.create(technology=row['technology'], circle=row['circle'], active_from=first, notes=reason)
        Change.objects.create(unit=unit, action='created', before={}, after={'technology': unit.technology, 'circle': unit.circle,
                              'active_from': first.isoformat(), 'active_until': None}, reason=reason)
    if not Threshold.objects.exists():
        Threshold.objects.create(value_pct=100, previous_value_pct=None, effective_from=date(2000, 1, 1),
                                 reason='Initial value: the existing CSV Arrival Tracker rule (every On-Air site of the unit has a record). '
                                        'To be confirmed by the business.')


